static void layer(const int16_t *in, const int16_t *w, const int16_t *b, int16_t *out, int rows, int cols, int relu) {
    for (int r = 0; r < rows; r++) {
        int64_t acc = 0;
        for (int c = 0; c < cols; c++)
            acc += (int32_t)w[r * cols + c] * (int32_t)in[c];
        acc >>= NN_SHIFT;
        acc += b[r];
        if (relu && acc < 0)
            acc = 0;
        if (acc > INT16_MAX)
            acc = INT16_MAX;
        if (acc < INT16_MIN)
            acc = INT16_MIN;
        out[r] = (int16_t)acc;
    }
}

